const visibleFarmers=[];function drawFarmers(){visibleFarmers.length=0;for(const a of farmers.active)visibleFarmers.push(a);if(isRaceMode(gameMode))for(const a of raceDecor.spectators)if(a.active&&Math.hypot(a.x-car.x,a.z-car.z)<RACE_DECOR_CONFIG.drawDistance)visibleFarmers.push(a);for(const a of visibleFarmers){const distance=Math.hypot(a.x-car.x,a.z-car.z),lod=a.hit?0:distance<40?0:distance<90?1:2;let root=matrix(a.x,a.y,a.z,a.scale||1,a.scale||1,a.scale||1,a.rotation);if(a.hit)root=mul(root,mul(rotateZ(a.tumble),rotateX(.9)));const swing=a.running?Math.sin(a.age*9+a.phase)*.28:Math.sin(a.age*2+a.phase)*.025,shirt=a.color||[.34,.46,.53],pants=[.22,.27,.31],skin=[.74,.57,.40],hat=[.53,.43,.26];function piece(x,y,z,w,h,d,color,tilt=0){draw(cube,mul(root,mul(matrix(x,y,z,1,1,1),mul(rotateX(tilt),matrix(0,0,0,w,h,d)))),color);}if(lod===2){piece(0,.87,0,.61,1.42,.34,shirt);piece(0,1.64,0,.37,.38,.34,hat);continue;}if(lod===1){piece(0,1.10,0,.58,.65,.34,shirt);piece(0,1.62,0,.36,.44,.34,skin);for(const side of [-1,1]){piece(side*.15,.43,0,.21,.78,.24,pants);piece(side*.40,1.30,0,.15,.60,.17,shirt,.85);}continue;}piece(0,1.10,0,.58,.65,.34,shirt);piece(0,1.59,.015,.33,.36,.32,skin);piece(0,1.80,0,.41,.12,.38,hat);piece(0,1.75,.20,.44,.04,.20,hat);for(const side of [-1,1]){piece(side*.15,.43,side*swing*.15,.21,.78,.24,pants,side*swing);piece(side*.40,a.scale?1.35:1.07,0,.15,.60,.17,shirt,a.scale?.85+Math.sin(a.age*3+a.phase)*.2:-side*swing);piece(side*.15,.10,.10,.23,.16,.36,[.12,.13,.11]);}piece(0,1.55,.19,.16,.055,.04,[.29,.24,.17]);}}

function formatTime(time){if(time==null)return '—';const minutes=Math.floor(time/60);return minutes+':'+(time%60).toFixed(2).padStart(5,'0');}
function updateRaceHUD(){const hud=document.querySelector('#race-hud');hud.hidden=menuOpen||!isRaceMode(gameMode);document.querySelector('#countdown').hidden=menuOpen||run.ended||cup.countdown>3||(cup.countdown<=0&&cup.time>1);document.querySelector('#countdown').textContent=cup.countdown>0?Math.ceil(cup.countdown):'ГАЗ!';if(!isRaceMode(gameMode))return;const r=cup.racers[0];if(!r)return;document.querySelector('#race-position').textContent='POS '+cup.position()+'/10';document.querySelector('#race-lap').textContent=world.finiteRace?(cup.progress.distance(r)/1000).toFixed(1)+' / '+(world.raceLength/1000).toFixed(1)+' KM':'LAP '+Math.min(3,r.laps+1)+'/3';document.querySelector('#race-times').textContent=world.finiteRace?'TIME '+formatTime(cup.time):'LAP '+formatTime(cup.time-r.lapStart)+' · LAST '+formatTime(r.lastLap)+' · BEST '+formatTime(r.bestLap);const countdown=document.querySelector('#countdown');countdown.textContent=cup.countdown>0?Math.ceil(cup.countdown):'ГАЗ!';countdown.hidden=cup.countdown>3||cup.time>1||cup.finished;}
function showMenu(){closeExit();garageOpen=false;document.querySelector('#garage-screen').hidden=true;run.save();physics.state.engineRunning=false;clear();menuOpen=true;menuSelection=0;cup.clear();raceDecor.clear();document.body.classList?.remove('circuit-mode');animals.clear();farmers.clear();traffic.clear();feedback.clear();runHUD.results.hidden=true;document.querySelector('#main-menu').hidden=false;document.querySelector('#cup-choices').hidden=true;document.querySelector('#cup-categories').hidden=false;document.querySelector('#sprint-choices').hidden=true;document.querySelector('#mode-choices').hidden=false;document.body.classList?.add('menu-open');document.querySelector('#menu-cup-stats').textContent='ПОБЕДЫ '+cup.stats.wins+' · ГОНОК '+cup.stats.races;document.querySelector('#menu-best').textContent='BEST '+(run.bestFor(GAME_MODE.ENDLESS)/1000).toFixed(1)+' KM';document.querySelector('#menu-offroad-best').textContent='BEST '+(run.bestFor(GAME_MODE.OFFROAD)/1000).toFixed(1)+' KM';document.querySelector('#race-hud').hidden=true;document.querySelector('#countdown').hidden=true;music.suspended=true;music.audio?.pause();}
function circuitRescueTarget(){const r=cup.racers[0],p=world.atDistance(r.acceptedS);return{section:p.section,u:p.u};}

function drawRacers(){if(!isRaceMode(gameMode))return;for(const r of cup.ai){if(r.dnf&&cup.time-r.dnfAt>3)continue;const remaining=(r.flashUntil||0)-cup.time,flashAge=.7-remaining;r.flashStrength=remaining>0&&(flashAge<.14||flashAge>.29&&flashAge<.44)?1:0;const b=r.body,distance=Math.hypot(b.p[0]-car.x,b.p[2]-car.z);if(distance>VIEW_CONFIG.drawDistance)continue;const lod=distance<60?0:distance<150?1:2;const mat=b.matrix(),colors={BODY:r.color,DARK:[.09,.10,.09],GLASS:[.24,.37,.41],METAL:[.64,.66,.61],LIGHT:[.88,.86,.69],RED:[.65,.18,.13]};for(const [key,shape] of Object.entries(raceLODMeshes[lod]))draw(shape,mat,colors[key],0,key==='LIGHT'?Math.max(environment.headlightIntensity*1.7,r.flashStrength*2.2||0):key==='RED'?(b.state.brake>.05?2.7:environment.headlightIntensity):0);for(const w of b.wheels){if(w.detached)continue;const point=b.point([w.x,b.c.mountHeight-w.length,w.z]),yaw=Math.atan2(mat[8],mat[10])+w.steer,m=mul(matrix(...point,1,1,1,yaw),rotateX(lod===2?0:w.angle));if(lod===2)draw(cube,mul(m,matrix(0,0,0,.25,.88,.88)),rubber);else draw(cylinder,mul(m,aiWheelAxle),rubber);}}
}
function drawStartFinish(){if(!isRaceMode(gameMode))return;for(const at of world.finiteRace?[CIRCUIT_CONFIG.startLine,world.raceFinishS]:[CIRCUIT_CONFIG.startLine]){const p=world.atDistance(at),root=matrix(p.x,p.y,p.z,1,1,1,p.yaw);for(const side of [-1,1])draw(cube,mul(root,matrix(side*5.6,2.65,0,.24,5.3,.24)),[.7,.69,.59]);draw(cube,mul(root,matrix(0,5.3,0,11.5,.9,.24)),[.31,.42,.34]);for(let i=0;i<12;i++)for(let j=0;j<2;j++)draw(cube,mul(root,matrix(-4.4+i*.8,.035,j*.42-.2,.79,.025,.4)),(i+j)%2?[.22,.24,.22]:[.86,.85,.72]);}for(let row=0;row<5;row++)for(const side of [-1,1]){const q=world.atDistance(CIRCUIT_CONFIG.gridFront-row*CIRCUIT_CONFIG.gridGap),m=matrix(q.x,q.y+.025,q.z,1,1,1,q.yaw);draw(cube,mul(m,matrix(side*1.6,0,0,1.9,.02,.10)),[.85,.84,.73]);}}
// Solo modes choose a build before entering the world; the Cup remains unchanged.
const garagePanel=document.querySelector('#garage-screen'),garageColors=document.querySelector('#garage-colors');
for(const [id,rgb] of Object.entries(PAINTS)){const button=document.createElement('button');button.type='button';button.dataset.tune='color';button.dataset.value=id;button.title=id.toUpperCase();const chip=document.createElement('span');chip.className='garage-color-dot';chip.style.background='rgb('+rgb.map(v=>Math.round(v*255)).join(',')+')';button.appendChild(chip);garageColors.appendChild(button);}
function paintGarageUI(){
 for(const button of garagePanel.querySelectorAll('[data-tune]')){const key=button.dataset.tune,value=button.dataset.value,chosen=value?garageBuild[key]===value:!!garageBuild[key];button.classList.toggle('selected',chosen);button.setAttribute('aria-pressed',String(chosen));if(!value)button.textContent=(chosen?'✓ ':'+ ')+button.textContent.replace(/^[✓+] /,'');}
 const preview=document.querySelector('#garage-car'),paint=PAINTS[garageBuild.color]||PAINTS.murena;preview.style.setProperty('--garage-paint','rgb('+paint.map(v=>Math.round(v*255)).join(',')+')');preview.classList.toggle('offroad',garageBuild.tires==='offroad');preview.classList.toggle('wide',garageBuild.arches);preview.classList.toggle('anime',garageBuild.livery==='anime');
 const selectedIndex=Math.max(0,LIVERY_CATALOG.findIndex(item=>item.id===garageBuild.livery));
 const selected=LIVERY_CATALOG[selectedIndex],asset=liveryAsset(selected.id);
 document.querySelector('#garage-livery-name').textContent=selected.name.toUpperCase();
 document.querySelector('#garage-livery-count').textContent=String(selectedIndex).padStart(2,'0')+' / '+String(LIVERY_CATALOG.length-1).padStart(2,'0');
 document.querySelector('#garage-livery-description').textContent=selected.tag;
 const art=document.querySelector('#garage-livery-art');
 art.hidden=!asset;
 if(asset&&art.getAttribute('src')!==asset)art.setAttribute('src',asset);
 if(!asset)art.removeAttribute('src');
 preview.querySelector('.garage-car-body').style.backgroundImage=asset?'url("'+asset+'")':'none';
 if(asset)bodyLivery.loadTexture(selected.id);
 const decal=document.querySelector('#garage-decal');decal.hidden=true;
 document.querySelector('#garage-summary').textContent=(garageBuild.tires==='offroad'?'ВНЕДОРОЖНАЯ РЕЗИНА':'ШОССЕЙНЫЕ ШИНЫ')+' · '+(garageBuild.engine==='turbo'?'ТУРБО':'СТОК');
}
garagePanel.addEventListener('click',e=>{const button=e.target.closest('[data-tune]');if(!button)return;const key=button.dataset.tune;if(!(key in STOCK_BUILD))return;garageBuild[key]=button.dataset.value||!garageBuild[key];garageBuild=saveBuild(localStore,garageBuild);paintGarageUI();});
function cycleLivery(direction){
 const current=Math.max(0,LIVERY_CATALOG.findIndex(item=>item.id===garageBuild.livery));
 garageBuild.livery=LIVERY_CATALOG[(current+direction+LIVERY_CATALOG.length)%LIVERY_CATALOG.length].id;
 garageBuild=saveBuild(localStore,garageBuild);
 paintGarageUI();
}
document.querySelector('#garage-livery-prev').addEventListener('click',()=>cycleLivery(-1));
document.querySelector('#garage-livery-next').addEventListener('click',()=>cycleLivery(1));
function showGarage(mode){garageMode=mode;garageOpen=true;menuOpen=true;menuSelection=0;document.querySelector('#main-menu').hidden=true;garagePanel.hidden=false;document.querySelector('#garage-heading').textContent=mode===GAME_MODE.OFFROAD?'НИВА · БЕЗДОРОЖЬЕ':'НИВА · РАЛЛИ';paintGarageUI();}
document.querySelector('#garage-back').addEventListener('click',()=>{garageOpen=false;garagePanel.hidden=true;showMenu();});
document.querySelector('#garage-start').addEventListener('click',()=>{garageBuild=saveBuild(localStore,garageBuild);startRun(garageMode);});
document.querySelector('#mode-endless').addEventListener('click',()=>showGarage(GAME_MODE.ENDLESS));document.querySelector('#mode-offroad').addEventListener('click',()=>showGarage(GAME_MODE.OFFROAD));document.querySelector('#mode-circuit').addEventListener('click',()=>{clear();menuSelection=0;document.querySelector('#mode-choices').hidden=true;document.querySelector('#cup-choices').hidden=false;});document.querySelector('#cup-sprint').addEventListener('click',()=>{menuSelection=0;document.querySelector('#cup-categories').hidden=true;document.querySelector('#sprint-choices').hidden=false;});document.querySelector('#cup-ring').addEventListener('click',()=>startRun(GAME_MODE.CIRCUIT));document.querySelector('#cup-sprint5').addEventListener('click',()=>startRun(GAME_MODE.SPRINT_5));document.querySelector('#cup-sprint10').addEventListener('click',()=>startRun(GAME_MODE.SPRINT_10));document.querySelector('#cup-back').addEventListener('click',()=>{if(!document.querySelector('#sprint-choices').hidden){document.querySelector('#sprint-choices').hidden=true;document.querySelector('#cup-categories').hidden=false;menuSelection=0;return;}document.querySelector('#cup-choices').hidden=true;document.querySelector('#cup-categories').hidden=false;document.querySelector('#sprint-choices').hidden=true;document.querySelector('#mode-choices').hidden=false;});document.querySelector('#back-menu').addEventListener('click',showMenu);showMenu();

function usesCinematicStart(){return !menuOpen&&cup.countdown>0&&isRaceMode(gameMode);}
function ceremonyCamera(){const elapsed=10-cup.countdown,grid=isRaceMode(gameMode)?world.atDistance(70):{x:physics.p[0],y:physics.p[1]-.8,z:physics.p[2],yaw:car.a},angle=grid.yaw-.9+elapsed*.38,radius=23-4*Math.min(1,elapsed/6),eye=[grid.x+Math.sin(angle)*radius,grid.y+7.0-Math.sin(elapsed*.35)*1.5,grid.z+Math.cos(angle)*radius],aim=[grid.x,grid.y+1.25,grid.z];if(elapsed>6){const blend=Math.min(1,(elapsed-6)/4),u=blend*blend*(3-2*blend),normalEye=cameraMode==='HOOD'?hood.p:camera;return{eye:eye.map((v,i)=>v*(1-u)+normalEye[i]*u),aim:aim.map((v,i)=>v*(1-u)+focus[i]*u)};}return{eye,aim};}
function drawRaceFlags(){if(!isRaceMode(gameMode)||!cup.progress)return;const next=cup.racers[0]?.nextGate;for(let i=0;i<cup.progress.gates.length;i++){const p=cup.progress.gates[i];if(Math.hypot(p.x-car.x,p.z-car.z)>200)continue;const active=i===next,root=matrix(p.x,p.y,p.z,1,1,1,p.yaw),color=active?[1.0,.76,.035]:[.19,.81,.66];for(const side of [-1,1]){const x=side*(p.width/2+2.5);draw(cube,mul(root,matrix(x,3.15,0,.10,6.3,.10)),[.88,.89,.79],0,.5);draw(cube,mul(root,matrix(x+side*.38,3.8,0,.76,4.8,.09)),color,0,active?1.5:.75);for(const y of [1.9,3.1,4.3,5.5])draw(cube,mul(root,matrix(x+side*.38,y,-.06,.55,.10,.025)),[.97,.97,.83],0,1);if(active)draw(cube,mul(root,matrix(x+side*.38,6.16,0,1.0,.20,.13)),[1,.88,.12],0,1.6);}}}

document.querySelector('#menu-button').addEventListener('click',openExit);document.querySelector('#stay-run').addEventListener('click',stayRun);document.querySelector('#exit-run').addEventListener('click',()=>{run.aborted=true;if(gameMode===GAME_MODE.ENDLESS||gameMode===GAME_MODE.OFFROAD)run.best=run.previousBest;showMenu();});
const racerLabels=[];const labelRoot=document.querySelector('#racer-labels');for(let i=0;i<9;i++){const element=document.createElement('div'),name=document.createElement('span'),track=document.createElement('div'),bar=document.createElement('i');element.className='racer-label';track.className='racer-hp';track.appendChild(bar);element.appendChild(name);element.appendChild(track);element.hidden=true;labelRoot.appendChild(element);racerLabels.push({element,name,track,bar});}
const labelLayout=new LabelLayout(),labelCandidates=Array.from({length:9},(_,id)=>({id,valid:false,box:{left:0,right:0,top:0,bottom:0}}));
function drawRacerLabels(){for(let i=0;i<9;i++){const l=racerLabels[i],r=cup.ai[i],c=labelCandidates[i];l.element.hidden=true;c.valid=false;if(menuOpen||!r||r.dnf)continue;const x=r.body.p[0],y=r.body.p[1]+2.8,z=r.body.p[2],distance=Math.hypot(x-physics.p[0],z-physics.p[2]),w=pv[3]*x+pv[7]*y+pv[11]*z+pv[15];if(distance>60||w<=0)continue;const sx=(pv[0]*x+pv[4]*y+pv[8]*z+pv[12])/w,sy=(pv[1]*x+pv[5]*y+pv[9]*z+pv[13])/w;if(Math.abs(sx)>1||Math.abs(sy)>1)continue;const px=(sx+1)*innerWidth/2,py=(1-sy)*innerHeight/2;let width=l.width;if(l.name.textContent!==r.name){l.name.textContent=r.name;const ctx=atlasContext,previousFont=ctx.font;ctx.font='bold 11px Arial';width=l.width=(ctx.measureText?.(r.name).width||r.name.length*7)+12;ctx.font=previousFont;}width=Math.max(70,width||70);c.valid=true;c.distance=distance;c.x=px;c.y=py;c.hp=distance<=30;Object.assign(c.box,{left:px-width/2,right:px+width/2,top:py-(c.hp?30:20),bottom:py});}for(const c of labelLayout.update(labelCandidates,Date.now())){const l=racerLabels[c.id],r=cup.ai[c.id];l.element.hidden=false;l.track.hidden=!c.hp;l.bar.style.transform='scaleX('+Math.max(0,r.run.hp/100)+')';l.element.style.transform='translate('+c.x+'px,'+c.y+'px) translate(-50%,-100%)';}}

